import csv
from io import StringIO

def load_completed(text):
    rows = csv.DictReader(StringIO(text))
    names = {name.strip().lower(): name for name in (rows.fieldnames or [])}
    required = {'lesson_id', 'completed_on'}
    if not required <= names.keys():
        raise ValueError('CSV needs lesson_id and completed_on columns.')

    result = []
    for number, row in enumerate(rows, start=2):
        lesson_id = row[names['lesson_id']]
        completed_on = row[names['completed_on']]
        if lesson_id is None or completed_on is None:
            raise ValueError(f'Row {number} is missing a field.')
        lesson_id, completed_on = lesson_id.strip(), completed_on.strip()
        if not lesson_id or not completed_on:
            raise ValueError(f'Row {number} has a blank required field.')
        result.append({'lesson_id': lesson_id, 'completed_on': completed_on})
    return result

text = ' lesson_id ,completed_on\nloops,2026-10-02\n'
print(load_completed(text))
